# --------------------------- the typed error ------------------------------ #

def test_localm_error_carries_summary_reason_context():
    e = bugreport.LocalmError("it broke", reason="because X", context={"a": 1})
    assert e.summary == "it broke"
    assert e.reason == "because X"
    assert e.context == {"a": 1}
    assert str(e) == "it broke"


# --------------------------- diagnostics ---------------------------------- #

def test_collect_diagnostics_is_safe_and_useful():
    diag = bugreport.collect_diagnostics({"operation": "test", "backend": "cuda"})
    assert "python" in diag and "platform" in diag
    assert diag.get("operation") == "test"
    assert diag.get("backend") == "cuda"
    # gpu_vendors is always present (possibly empty), never raises.
    assert "gpu_vendors" in diag


def test_collect_diagnostics_never_includes_env_secrets(monkeypatch):
    monkeypatch.setenv("LOCALM_API_KEY", "super-secret-value")
    diag = bugreport.collect_diagnostics({})
    assert "super-secret-value" not in repr(diag)


# --------------------------- report rendering ----------------------------- #

def test_build_report_has_sections_and_summary():
    text = bugreport.build_report("disk on fire", reason="too hot",
                                  context={"operation": "run"})
    assert "# localm bug report: disk on fire" in text
    assert "## What I was doing" in text
    assert "## Environment" in text
    assert "too hot" in text
    assert bugreport.MAINTAINER_EMAIL in text   # contact line, intentionally


def test_report_footer_strip_removes_exactly_the_disclaimer_block():
    """LM-DA-PUBTEXT: the in-app 'edit before sending' disclaimer (and the maintainer's email that rides with it) must be removable from a real build_report() output as a single, exact, single-sourced block - not a fuzzy substring match that could also eat real report content."""
    text = bugreport.build_report("disk on fire", reason="too hot")
    assert bugreport.MAINTAINER_EMAIL in text
    assert "You can edit anything above before sending." in text

    stripped = bugreport._strip_report_footer(text)
    assert bugreport.MAINTAINER_EMAIL not in stripped
    assert "You can edit anything above before sending." not in stripped
    # Nothing else was touched - the stripped text is a strict prefix of the
    # original (only the trailing footer block is gone).
    assert text.startswith(stripped)
    assert "disk on fire" in stripped
    assert "too hot" in stripped


def test_report_footer_strip_tolerates_missing_trailing_newline():
    """A user who re-saves the file in an editor that trims trailing whitespace must still get a clean strip, not a silent no-op."""
    text = bugreport.build_report("x")
    without_trailing_newline = text.rstrip("\n")
    stripped = bugreport._strip_report_footer(without_trailing_newline)
    assert bugreport.MAINTAINER_EMAIL not in stripped


def test_report_footer_strip_is_a_noop_when_footer_absent():
    """A body that never had the footer (or had it manually edited away) must come back byte-for-byte unchanged - never raise, never eat real content."""
    plain = "## What happened\nsomething broke, no footer here"
    assert bugreport._strip_report_footer(plain) == plain
    assert bugreport._strip_report_footer("") == ""


def test_build_report_includes_error_traceback():
    try:
        raise ValueError("boom")
    except ValueError as e:
        text = bugreport.build_report("crashed", error=e)
    assert "## Error detail" in text
    assert "ValueError: boom" in text


def test_build_report_scrubs_credentialed_url_in_error_traceback():
    """HON-15: an exception message can embed a user-configured credentialed URL (a comfy_api_url / net_search_url / remote-server base with user:pass@), and the traceback ships in the uploaded 'Error detail' body."""
    try:
        raise RuntimeError("Could not reach the localm server at "
                           "http://user:SECRETPASS@remote:8000/v1: timeout")
    except RuntimeError as e:
        text = bugreport.build_report("server unreachable", error=e)
    assert "## Error detail" in text
    assert "SECRETPASS" not in text
    assert "<redacted>" in text


# A credential is at least as often carried as a URL QUERY PARAMETER
# (?api_key=...) or a pasted HTTP header line (X-Api-Key: ...) as it is via
# user:pass@ syntax. Both shapes are asserted in ONE block together with the
# user:pass@ case: if a regression ever deletes the _scrub_secrets call
# entirely, a query-only test would still pass while user:pass@ silently
# started leaking again (QA-FINDING-bugreport-url-query-secret-leak-2026-08-13).
def test_scrub_secrets_redacts_credential_query_params_by_name():
    out = bugreport._scrub_secrets(
        "https://x.example/s?api_key=CANARY1&token=CANARY2"
        "&apikey=CANARY3&key=CANARY4")
    assert "CANARY1" not in out
    assert "CANARY2" not in out
    assert "CANARY3" not in out
    assert "CANARY4" not in out
    # The parameter NAME survives - the maintainer needs to see the endpoint
    # was credentialed and which one, only the value must go.
    assert "api_key=<redacted>" in out
    assert "token=<redacted>" in out
    assert "apikey=<redacted>" in out
    assert "key=<redacted>" in out


def test_scrub_secrets_leaves_non_credential_query_params_intact():
    """Over-redaction destroys the diagnostic value of a report and is a real failure mode here - a plain search/lang parameter must not be touched."""
    out = bugreport._scrub_secrets("https://x.example/s?q=hello&lang=en")
    assert out == "https://x.example/s?q=hello&lang=en"


def test_scrub_secrets_still_redacts_user_pass_at_url_creds():
    """Same assertion block as the query-param cases above, deliberately - see the module comment on this test group."""
    out = bugreport._scrub_secrets("http://user:SECRETPASS@remote:8000/v1")
    assert "SECRETPASS" not in out
    assert "<redacted>" in out


def test_scrub_secrets_redacts_credential_header_line():
    out = bugreport._scrub_secrets("X-Api-Key: CANARY5")
    assert "CANARY5" not in out
    assert "X-Api-Key: <redacted>" in out


def test_scrub_secrets_query_and_header_redaction_is_idempotent():
    once = bugreport._scrub_secrets(
        "https://x.example/s?api_key=CANARY1&q=hello -- X-Api-Key: CANARY2")
    twice = bugreport._scrub_secrets(once)
    assert once == twice
    assert "CANARY1" not in once and "CANARY2" not in once


# The credential NAME does not have to sit right after a ? or & - a user pasting
# a .env fragment, a shell line or a printed launcher URL into a report writes it
# at the start of a line, or behind a prefix (OPENAI_API_KEY=, pull_token=) that
# never touches a query delimiter at all. Every one of those shipped verbatim
# until _QUERY_SECRET_RE grew its bare-name branches.
#
# CANARY CHOICE IS LOAD-BEARING: these canaries match none of the OTHER scrubbers
# in the chain. An sk- shaped canary would be eaten by _APIKEY_RE and make the
# test pass on the unfixed pattern - green for a reason unrelated to the fix.
def test_scrub_secrets_redacts_bare_credential_assignment_outside_a_url():
    out = bugreport._scrub_secrets(
        "pasted from my .env:\napi_key=CANARYBARE7Q4M\ntoken=CANARYBARE9VLM\n")
    # The DATA first: a regression must report "the canary survived", which is a
    # statement about the world. Leading with the <redacted> marker would read as
    # an adjustable formatting nit and invite someone to edit the assertion.
    assert "CANARYBARE7Q4M" not in out
    assert "CANARYBARE9VLM" not in out
    # The marker second - the name still shows THAT a credential was there.
    assert "api_key=<redacted>" in out
    assert "token=<redacted>" in out


def test_scrub_secrets_redacts_prefixed_credential_names():
    """SECRET_KEY / PRIVATE_KEY / OPENAI_API_KEY are the shapes a .env actually carries, and none of them can reach the ?/& anchored form."""
    out = bugreport._scrub_secrets(
        "OPENAI_API_KEY=CANARYBARE1AAA SECRET_KEY=CANARYBARE2BBB "
        "PRIVATE_KEY=CANARYBARE3CCC x-auth=CANARYBARE4DDD")
    for canary in ("CANARYBARE1AAA", "CANARYBARE2BBB",
                   "CANARYBARE3CCC", "CANARYBARE4DDD"):
        assert canary not in out
    assert "OPENAI_API_KEY=<redacted>" in out
    assert "SECRET_KEY=<redacted>" in out
    assert "x-auth=<redacted>" in out


def test_scrub_secrets_redacts_launch_grants_in_a_printed_gui_url():
    """``localm gui`` puts its pull/launch grants in the URL it prints to the console, so this is the one shape known to reach a report carrying a real (short-lived, single-use) credential. It has a prefixed parameter name, so the ?/& anchored form left the whole line untouched."""
    out = bugreport._scrub_secrets(
        "opening https://127.0.0.1:8080/?view=models&pull=owner%2Frepo"
        "&pull_token=CANARYBARE5EEE&localm_token=CANARYBARE6FFF")
    assert "CANARYBARE5EEE" not in out
    assert "CANARYBARE6FFF" not in out
    assert "pull_token=<redacted>" in out
    assert "localm_token=<redacted>" in out
    assert "pull=owner%2Frepo" in out


def test_scrub_secrets_leaves_non_credential_bare_assignments_intact():
    """The OTHER failure direction, and the one with no natural signal: an over-broad pattern ships green and silently eats diagnostic text out of every report."""
    text = ("n_gpu_layers=35 port=8080 n_ctx=4096 max_tokens=512 model=llama "
            "monkey=13 hotkey=f1 key=value auth=none sig=short")
    assert bugreport._scrub_secrets(text) == text


def test_scrub_secrets_bare_assignment_redaction_is_idempotent():
    once = bugreport._scrub_secrets(
        "api_key=CANARYBARE7Q4M SECRET_KEY=CANARYBARE2BBB n_ctx=4096")
    twice = bugreport._scrub_secrets(once)
    assert once == twice
    assert "CANARYBARE7Q4M" not in once and "CANARYBARE2BBB" not in once


# The name-based match is deliberately broad, so it needs a floor on the other
# side. These values were NOT invented: they are the shapes a scan of this repo's
# own tracked docs and sources found the name match eating before the non-secret
# literal suppressor was added. Picking fixture values out of imagination is how
# the over-redaction direction went untested in the first place.
_NON_SECRET_ASSIGNMENTS = (
    "LOCALM_REQUIRE_AUTH=1",
    "require_auth=true",
    "digital_signature=True",
    "secret=True",
    "has_token=false",
    "password=None",
    "signature=None",
    "auth_token=none",
    "api_key=disabled",
    "pull_token=null",
    # A report is prose, so the same flag arrives wrapped in markup. Found by a
    # test bound to the real docs, which write it as markdown inline code - the
    # first version of the suppressor missed every one of these.
    "`require_auth=1`",
    "(require_auth=1)",
    "`LOCALM_REQUIRE_AUTH=1`",
    "set `require_auth=true` to fail closed",
    'require_auth="true"',
    "require_auth='true'",
)


@pytest.mark.parametrize("line", _NON_SECRET_ASSIGNMENTS)
def test_scrub_secrets_keeps_assignments_whose_value_cannot_be_a_secret(line):
    """Over-redaction has no natural failure signal: an over-broad pattern ships green and silently eats diagnostic text out of every report."""
    assert bugreport._scrub_secrets(line) == line


# The suppressor must not become a bypass: a real secret that merely STARTS with
# one of the literals has to keep going. The inner lookahead pins each literal to
# the WHOLE value, and this is the test that holds it there.
@pytest.mark.parametrize("line,canary", [
    ("api_key=trueCANARYLIT1", "trueCANARYLIT1"),
    ("token=noCANARYLIT2", "noCANARYLIT2"),
    ("api_key=onCANARYLIT3", "onCANARYLIT3"),
    ("SECRET_KEY=falseCANARYLIT4", "falseCANARYLIT4"),
    ("api_key=0CANARYLIT5", "0CANARYLIT5"),
    ("api_key=10", "10"),
])
def test_scrub_secrets_still_redacts_a_secret_that_starts_with_a_literal(line, canary):
    out = bugreport._scrub_secrets(line)
    assert canary not in out          # DATA first
    assert "=<redacted>" in out       # marker second


@pytest.mark.parametrize("line", [
    "api_key=1)SECRETLEAK",
    'api_key=1"SECRETLEAK',
    "token=true]MORESECRET",
])
def test_the_non_secret_suppressor_does_not_fire_when_more_value_follows(line):
    """Tolerating closing markup must not become a bypass. ``(require_auth=1)`` is a flag; ``api_key=1)SECRET`` is not, and the difference is whether anything other than whitespace follows the markup."""
    out = bugreport._scrub_secrets(line)
    assert "=<redacted>" in out, (
        f"the suppressor swallowed a credential assignment: {out!r}")


# FOUND BY A LIVE RUN, not by the suite: filing a real report through the CLI
# with a pasted .env produced
#
#     API_KEY=<redacted>"ENVQUOTEDSECRET1"
#
# The value stopped at the opening quote, so the secret shipped in full sitting
# next to a marker claiming it had been removed. A quoted value is the COMMON
# .env form, and every fixture in this file had used the bare form.
#
# Worse than a plain miss: a privacy step reporting a success it did not achieve
# is the one thing AGENTS.md rule 5 forbids outright.
@pytest.mark.parametrize("line,canary", [
    ('API_KEY="ENVQUOTED1"', "ENVQUOTED1"),
    ("SECRET_KEY='ENVQUOTED2'", "ENVQUOTED2"),
    ('api_key="with spaces inside"', "with spaces inside"),
    ('OPENAI_API_KEY="sk-ENVQUOTED3"', "ENVQUOTED3"),
    ('?api_key="ENVQUOTED4"&x=1', "ENVQUOTED4"),
    # An unterminated quote redacts to end of line. Over-redacting the rest of a
    # line that opened with a credential is the safe direction.
    ('api_key="ENVQUOTED5', "ENVQUOTED5"),
    ("api_key='ENVQUOTED6", "ENVQUOTED6"),
])
def test_scrub_secrets_redacts_a_quoted_credential_value(line, canary):
    out = bugreport._scrub_secrets(line)
    # DATA first: a regression must say the canary survived.
    assert canary not in out, (
        f"a quoted credential shipped verbatim: {out!r}")
    assert "=<redacted>" in out


def test_unterminated_quote_redaction_span_is_what_the_comment_claims():
    """The three spans an unterminated quote can produce, pinned because the comment beside the pattern got one of them wrong: it claimed end-of-line in all cases, when a later quote on the same line ends the span earlier."""
    # no later quote: to end of line
    out = bugreport._scrub_secrets("api_key=\"UNTERM1 and more text here")
    assert "UNTERM1" not in out
    assert out == "api_key=<redacted>"
    # a later quote on the same line: the span ends THERE, not at end of line
    out = bugreport._scrub_secrets(
        "api_key=\"UNTERM2 then require_auth=\"true\" after")
    assert "UNTERM2" not in out
    assert out.endswith("after"), out
    # never across a newline: the next line is untouched
    out = bugreport._scrub_secrets("api_key=\"UNTERM3\nn_gpu_layers=35")
    assert "UNTERM3" not in out
    assert "n_gpu_layers=35" in out


def test_scrub_secrets_never_marks_redacted_while_leaving_the_secret():
    """The specific shape the live run produced."""
    out = bugreport._scrub_secrets('my .env has API_KEY="ENVQUOTED7"')
    assert "ENVQUOTED7" not in out
    assert '<redacted>"' not in out, (
        f"a redaction marker was emitted immediately before a surviving quoted "
        f"value: {out!r}")


def test_scrub_secrets_never_eats_a_non_secret_value_out_of_the_real_docs():
    """Bound to the SHIPPED artefact, not to a fixture."""
    docs = pathlib.Path(bugreport.__file__).resolve().parents[1] / "docs"
    assert docs.is_dir(), f"docs/ not found next to the package: {docs}"
    files = sorted(docs.rglob("*.md"))
    assert len(files) > 5, f"instrument broken: only found {len(files)} docs"

    literals = {"true", "false", "none", "null", "nil", "yes", "no",
                "on", "off", "enabled", "disabled", "0", "1"}
    seen, eaten = 0, []
    for f in files:
        text = f.read_text(encoding="utf-8", errors="replace")
        for m in bugreport._QUERY_SECRET_RE.finditer(text):
            seen += 1
            # The docs write flags as markdown inline code, so the captured value
            # is ``1` `` and not ``1`` (a backtick does not terminate the value).
            # Comparing the RAW value made this test unable to fail: it passed
            # with the suppressor removed. Strip the surrounding markup first.
            value = m.group(0)[len(m.group(1)):].strip("`*_.,;:)]}").lower()
            if value in literals:
                line_no = text.count("\n", 0, m.start()) + 1
                eaten.append(f"{f.name}:{line_no} {m.group(0)!r}")
    # Prove the scan can see anything at all. If the docs ever stop containing a
    # credential-named assignment, this test becomes vacuous, and it should say
    # so loudly rather than keep reporting a green it did not earn.
    assert seen > 0, (
        "no credential-named assignment found anywhere in the docs - this test "
        "can no longer detect the regression it exists for")
    assert eaten == [], (
        "the scrub redacted a value that cannot be a secret, out of real shipped "
        f"docs: {eaten}")


