def test_report_failure_noninteractive_saves_without_prompt(tmp_path, monkeypatch, capsys):
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
    opened = []
    path = bugreport.report_failure(
        summary="thing broke", reason="reason Y",
        interactive=False, open_browser=lambda u: opened.append(u),
        prompt=lambda _t: (_ for _ in ()).throw(AssertionError("should not prompt")))
    out = capsys.readouterr().out
    assert "Sorry - thing broke" in out
    assert "reason Y" in out
    assert path is not None and path.exists()
    assert opened == []              # never opens a browser unattended


def test_report_failure_email_channel_opens_mailto(tmp_path, monkeypatch):
    monkeypatch.setattr("localm.config.home_dir", lambda: tmp_path)
